118→func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
119→	expiry := time.Duration(expiresIn) * time.Second
120→	if expiry <= 0 || expiry > maxExpiresIn {
121→		expiry = maxExpiresIn
122→	}
123→	deadline := time.Now().Add(expiry)
124→	pollInterval := time.Duration(interval) * time.Second
125→	if pollInterval <= 0 {
126→		pollInterval = fallbackDeviceAuthPollInterval
127→	}
128→
129→	consecutiveErrors := 0
130→
131→	for {
132→		if time.Now().After(deadline) {
133→			return "", errors.New("device authorization expired")
134→		}
135→
136→		result, err := poller.PollDeviceAuth(ctx, deviceCode)
137→		if err != nil {
138→			consecutiveErrors++
139→			if consecutiveErrors >= maxTransientErrors {
140→				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
141→			}
142→			// Transient error — wait and retry.
143→			select {
144→			case <-ctx.Done():
145→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
146→			case <-time.After(pollInterval):
147→			}
148→			continue
149→		}
150→		consecutiveErrors = 0
151→
152→		switch result.Error {
153→		case "":
154→			if result.AccessToken == "" {
155→				return "", errors.New("device authorization completed without a token")
156→			}
157→			return result.AccessToken, nil
158→		case "authorization_pending":
159→			// no-op, will sleep and retry below
160→		case "slow_down":
161→			pollInterval += slowDownBackoff
162→			if pollInterval > maxPollInterval {
163→				pollInterval = maxPollInterval
164→			}
165→		case "access_denied":
166→			return "", errors.New("device authorization denied")
167→		case "expired_token":
168→			return "", errors.New("device authorization expired")
169→		default:
170→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
171→		}
172→
173→		select {
174→		case <-ctx.Done():
175→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
176→		case <-time.After(pollInterval):
177→		}
178→	}
179→}
