181→// waitForEnter reads a line from /dev/tty, blocking until the user presses Enter.
182→// If /dev/tty cannot be opened (e.g. on Windows), it returns immediately.
183→func waitForEnter() {
184→	tty, err := os.Open("/dev/tty")
185→	if err != nil {
186→		return
187→	}
188→	defer tty.Close()
189→
190→	reader := bufio.NewReader(tty)
191→	if _, err = reader.ReadString('\n'); err != nil {
192→		return
193→	}
194→}
