196→func openBrowser(ctx context.Context, browserURL string) error {
197→	u, err := url.Parse(browserURL)
198→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
199→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
200→	}
201→
202→	var command string
203→	var args []string
204→
205→	switch runtime.GOOS {
206→	case "darwin":
207→		command = "open"
208→		args = []string{browserURL}
209→	case "linux":
210→		command = "xdg-open"
211→		args = []string{browserURL}
212→	case "windows":
213→		command = "cmd"
214→		args = []string{"/c", "start", "", browserURL}
215→	default:
216→		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
217→	}
218→
219→	cmd := exec.CommandContext(ctx, command, args...)
220→	if err := cmd.Start(); err != nil {
221→		return fmt.Errorf("start browser command %q: %w", command, err)
222→	}
223→
224→	if err := cmd.Process.Release(); err != nil {
225→		return fmt.Errorf("release browser process: %w", err)
226→	}
227→
228→	return nil
229→}
